class FeatureFlags:
    def __init__(self):
        self.flags = {}

    def set(self, name, enabled):
        if name in self.flags:
            self.flags[name] = enabled
        else:
            print(f"Warning: {name} is not a known feature flag.")

    def get(self, name):
        if name in self.flags:
            return self.flags[name]
        else:
            return False

