class EventStore:
    def __init__(self):
        self.events = {}

    def record(self, user, value):
        if user in self.events:
            self.events[user].append(value)
        else:
            self.events[user] = [value]

    def latest(self, user):
        if user in self.events:
            return self.events[user][-1]
        else:
            return None

class EventStore:
    def __init__(self):
        self.store = {}

    def record(self, user, value):
        if user not in self.store:
            self.store[user] = []
        self.store[user].append(value)

    def latest(self, user):
        if user in self.store:
            return self.store[user][-1] if self.store[user] else None
        return None

