        }

    def resolve(self, path):
        if path in self.routes:
            return self.routes[path]
        return None

class Router:
    def __init__(self):
        self.routes = {}

    def add_route(self, path, handler):
        self.routes[path] = handler

    def resolve(self, path):
        return self.routes.get(path, None)

